function addMesh(geo,material,x,y,z,sx=1,sy=1,sz=1,shadow=true){const m=new THREE.Mesh(geo,material);m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.castShadow=shadow;m.receiveShadow=true;scene.add(m);return m}
function heightAt(x,z){const r=Math.hypot(x,z);let edge=THREE.MathUtils.smoothstep(r,70,103);let h=(Math.sin(x*.055+1)*Math.cos(z*.047)+Math.sin(z*.09+x*.03)*.35)*2.1;h+=Math.max(0,1-Math.hypot(x+35,z+35)/48)*13;h+=Math.max(0,1-Math.hypot(x-56,z-29)/29)*8;h+=Math.max(0,1-Math.hypot(x-8,z+69)/20)*4;return h*(1-edge)-1.5*edge}
function makeTerrain(){const n=140,size=220,geo=new THREE.PlaneGeometry(size,size,n,n);geo.rotateX(-Math.PI/2);const p=geo.attributes.position,colors=[];const c1=new THREE.Color(0x88a16e),c2=new THREE.Color(0xb8b07e),c3=new THREE.Color(0x787e6c);for(let i=0;i<p.count;i++){const x=p.getX(i),z=p.getZ(i),h=heightAt(x,z);p.setY(i,h);let c=h<.3?c2:(h>6?c3:c1);let noise=(Math.sin(x*2.7+z*1.1)*Math.cos(z*2.3-x*.4)+1)*.025;c=c.clone().offsetHSL(0,0,noise);colors.push(c.r,c.g,c.b)}geo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));geo.computeVertexNormals();const terrain=new THREE.Mesh(geo,new THREE.MeshStandardMaterial({vertexColors:true,roughness:1}));terrain.receiveShadow=true;scene.add(terrain);
